import {esc} from './organiser-utils.js';
import {dueLabel} from './workspace-summary.js';
import {reviewView} from './leadership-review.js';
import {registry,finance,deskName,handoffDesk} from './department-tools.js';
const read=async q=>{const r=await q;if(r.error)throw r.error;return r.data};
const formatMoney=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(n);
const copy={finance:'Record receipts and spending, attach bills and reconcile the approved accounts.',social:'Plan the next post, draft the copy and send it for review before scheduling.',media:'Develop creative briefs, collect references and submit artwork for approval.',outreach:'Track school contacts, conversations and the date of the next follow-up.',partnerships:'Follow each sponsor from the first conversation through agreed deliverables.',operations:'Keep suppliers, venues, transport and due dates together.',programme:'Plan sessions, room allocations, facilitators and equipment.',general:'Keep your department’s plans, owners and supporting material together.'};
const href=x=>{try{const u=new URL(x);return u.protocol==='https:'?esc(u.href):null}catch{return null}};
const empty=(title,body)=>'<div class="ops-empty"><b>'+esc(title)+'</b><p>'+esc(body)+'</p></div>';
const btn=(k,label)=>'<button type="button" data-go="'+esc(k)+'">'+esc(label)+' <span aria-hidden="true">↗</span></button>';
export async function operationsDesk({host,sb,session,mine,reviewer,signout,composer}){
 const leadership=!!reviewer,lead=mine?.role==='lead',manage=lead||leadership;
 const title=leadership?(reviewer.seat==='director'?'Director':'Assistant Director'):(lead?'Department head':'Committee member');
 const nav={home:'Overview',tasks:leadership?'Work across teams':lead?'Team tasks':'My tasks',teams:leadership?'Departments':'My team',decisions:leadership?'Approval inbox':'My department’s reviews',briefs:'Briefings & resources',handoffs:'Handoffs',...(leadership?{money:'Finance overview'}:{}),...(mine?{tools:'Department tools'}:{})};
 host.innerHTML='<div class="ops-layout"><aside class="ops-rail"><div><small>ÉLAN / OPERATIONS</small><h2>'+esc(title)+'</h2><p>'+esc(leadership?'Summit leadership':mine.department)+'</p></div><nav aria-label="Organiser workspace">'+Object.entries(nav).map(([k,v])=>'<button data-go="'+k+'">'+esc(v)+'</button>').join('')+'</nav><button class="ops-signout">Sign out</button></aside><section class="ops-canvas" aria-live="polite"></section></div>';
 host.querySelector('.ops-signout').onclick=signout;
 const view=host.querySelector('.ops-canvas');let generation=0,active='home',filter='';
 host.onclick=e=>{const b=e.target.closest('[data-go]');if(b){filter=b.dataset.dept||'';render(b.dataset.go);}};
 async function render(tab){if(!Object.hasOwn(nav,tab))return;active=tab;const g=++generation;const panel=document.createElement('div');view.replaceChildren(panel);panel.innerHTML='<p role="status">Loading workspace…</p>';
 for(const b of host.querySelectorAll('.ops-rail [data-go]'))b.setAttribute('aria-current',b.dataset.go===tab?'page':'false');
 try{
 const [s,ctx,count]=await Promise.all([read(sb.rpc('elan_ops_desk')),read(sb.rpc('elan_desk_context')),sb.from('elan_oc_requests').select('id',{count:'exact',head:true}).eq('status','pending')]);if(g!==generation)return;if(count.error)throw count.error;
 const pending=count.count||0,open=s.tasks.filter(t=>t.status!=='Done'),who=id=>s.people.find(p=>p.id===id)?.name||'Assigned organiser',today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 const work=t=>'<article class="ops-row"><div><small>'+esc(t.department)+'</small><h3>'+esc(t.title)+'</h3><p>'+esc(who(t.assigned_to))+' · '+esc(t.status)+'</p></div><span class="ops-tag">'+esc(dueLabel(t,today))+'</span></article>';
 const hero=(name,sub)=>'<header class="ops-head"><small>ÉLAN 2027 &nbsp; / &nbsp; '+esc(title)+'</small><h1>'+esc(name)+'</h1><p>'+esc(sub)+'</p></header>';
 const formBind=(form,fn)=>{form.onsubmit=async e=>{e.preventDefault();if(form.inert||!form.reportValidity())return;form.inert=true;const note=form.querySelector('[role=status]');try{await fn(Object.fromEntries(new FormData(form)));await render(active);}catch(err){note.textContent=err.message;}finally{form.inert=false;}};};
 const deptOptions=()=>s.teams.map(m=>'<option'+(filter===m.department?' selected':'')+'>'+esc(m.department)+'</option>').join('');
 const waiting=['director','assistant'].filter(k=>!ctx.seats.includes(k)).map(k=>k==='director'?'Director':'Assistant Director');
 const seatNotice=waiting.length?'<aside class="ops-empty"><b>Approvals are waiting for an appointment</b><p>The '+esc(waiting.join(' and '))+' seat is not active. Teams can submit work now; final approval requires both leaders.</p></aside>':'';
 if(tab==='home'){
 const mod=s.teams.find(t=>t.department===mine?.department);
 panel.innerHTML='<header class="ops-cover"><div><small>ÉLAN SUMMIT &nbsp; / &nbsp; ORGANISING COMMITTEE 2027</small><h1>'+esc(leadership?'Summit operations':mine.department)+'</h1><p>'+esc(leadership?'Set priorities, brief the teams and see what needs a decision.':copy[mod?.tool]||copy.general)+'</p></div></header>'+seatNotice+'<div class="ops-metrics">'+[[open.length,'Open tasks','tasks'],[open.filter(t=>t.due_on&&t.due_on<today).length,'Overdue','tasks'],[pending,'Awaiting approval','decisions'],[s.people.length,'Active organisers','teams']].map(([n,l,k])=>'<button data-go="'+k+'"><small>'+l+'</small><b>'+n+'</b></button>').join('')+'</div><div class="ops-columns"><section class="ops-paper"><small>WORK PLAN</small><h2>Coming up</h2>'+ (open.length?open.slice(0,4).map(work).join(''):empty('Your task board is clear.',manage?'Start by assigning a responsibility and its deadline.':'Assigned work and deadlines will appear here.'))+btn('tasks',manage?'Plan and assign work':'Open my tasks')+'</section><section class="ops-paper ops-ink"><small>WORKSPACE SHORTCUTS</small><h2>'+esc(leadership?'Lead the summit':'Department desk')+'</h2>'+btn(leadership?'briefs':'tools',leadership?'Brief a department':deskName(mod))+btn('decisions',leadership?'Review submissions':'Track submitted work')+btn(leadership?'money':'handoffs',leadership?'View approved finances':'Check handoffs')+'</section></div>';if(ctx.coordination&&!leadership)panel.insertAdjacentHTML('beforeend','<section class="ops-paper"><small>ACROSS DEPARTMENTS</small><h2>Team workload</h2>'+ctx.coordination.map(t=>'<p><b>'+esc(t.department)+'</b> · '+t.open+' open · '+t.late+' overdue · '+t.pending+' awaiting review</p>').join('')+'</section>');return;}
 panel.innerHTML=hero(nav[tab],({tasks:'Responsibilities, owners and deadlines.',teams:'Find the people behind each department and see what they’re working on.',decisions:'Review the evidence and follow both leadership decisions.',briefs:'Instructions and reference material for the organising team.',handoffs:'Responsibilities passed between departments.',tools:copy[s.teams.find(x=>x.department===mine?.department)?.tool]||copy.general,money:'Figures below come from posted transactions through today.'})[tab])+'<div class="ops-content"></div>';
 const box=panel.querySelector('.ops-content');
 if(tab==='decisions'){await reviewView(box,sb,reviewer?.seat);return;}
 if(tab==='tools'){const mod=s.teams.find(x=>x.department===mine.department);if(!mod?.id){box.innerHTML=empty('Department register is not configured.','Ask the administrator to configure the department workspace.');return;}await (mod.tool==='finance'?finance:registry)({box,sb,mod,lead,user:session.user.id,destinations:ctx.departments});return;}
 if(tab==='teams'){box.innerHTML=s.teams.map((m,i)=>'<article class="ops-team"><small>DEPARTMENT '+String(i+1).padStart(2,'0')+'</small><h2>'+esc(m.department)+'</h2><p>'+esc(copy[m.tool]||copy.general)+'</p><p>'+esc(s.people.filter(p=>p.department===m.department).map(p=>p.name+(p.role==='lead'?' (head)':'')).join(' · ')||'No active members assigned yet.')+'</p><button data-go="tasks" data-dept="'+esc(m.department)+'">View tasks →</button>'+ (leadership?'<details><summary>Approved department work</summary>'+ (s.registers.filter(r=>r.department===m.department).map(r=>'<p>'+esc(r.title)+' · '+esc(r.stage||'Approved')+'</p>').join('')||'<p>No approved register entries yet.</p>')+'</details>':'')+'</article>').join('');return;}
 if(tab==='tasks'){const list=s.tasks.filter(t=>!filter||filter===t.department);box.innerHTML=(manage&&s.people.length?'<details class="ops-action" '+(!list.length?'open':'')+'><summary>Assign a task</summary><form class="team-form"><label>Owner<select name="owner" required><option value="">Choose an organiser</option>'+s.people.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.department+' · '+p.name)+'</option>').join('')+'</select></label><label>Responsibility<input name="title" maxlength="200" required></label><label>Instructions<textarea name="brief" maxlength="2500"></textarea></label><label>Due date<input name="due" type="date" required></label><button>Assign task</button><p role="status"></p></form></details>':manage?empty('Assignment needs an active organiser.','The owner can appoint members in Admin. You can already publish a briefing for an empty department.'):'')+(leadership?'<label>Department<select data-filter><option value="">All departments</option>'+deptOptions()+'</select></label>':'')+(list.length?list.map(t=>work(t)+((mine&&mine.department===t.department&&(lead||t.assigned_to===session.user.id))?'<form class="ops-update" data-task="'+esc(t.id)+'"><label>Progress<select name="state">'+['Open','In progress','Done'].map(k=>'<option '+(k===t.status?'selected':'')+'>'+k+'</option>').join('')+'</select></label><button>Save status</button><p role="status"></p></form>':'')+'<p class="ops-brief">'+esc(t.brief)+'</p>').join(''):empty('No tasks here yet.',manage?'Assign a task using the form above.':'Your head can assign your next responsibility here.'));
 const f=box.querySelector('.team-form');if(f)formBind(f,v=>read(sb.rpc('elan_ops_assign',{p_owner:v.owner,p_title:v.title,p_brief:v.brief,p_due:v.due})));const dd=box.querySelector('[data-filter]');if(dd)dd.onchange=()=>{filter=dd.value;render('tasks');};for(const f of box.querySelectorAll('[data-task]'))formBind(f,v=>read(sb.rpc('elan_oc_progress',{p_id:f.dataset.task,p_status:v.state})));return;}
 if(tab==='briefs'){box.innerHTML=(leadership?'<details class="ops-action"><summary>Issue a department briefing</summary><form class="team-form"><label>Department<select name="dept">'+deptOptions()+'</select></label><label>Title<input name="title" maxlength="160" required></label><label>Instructions<textarea name="body" maxlength="4000" required></textarea></label><button>Publish briefing</button><p role="status"></p></form></details>':'')+(lead?'<details class="ops-action"><summary>Propose a briefing or resource</summary><div data-compose></div></details>':'')+ (s.posts.map(p=>'<article class="ops-row"><div><small>'+esc(p.department+' / '+p.kind)+'</small><h3>'+esc(p.title)+'</h3><p>'+esc(p.body)+'</p>'+(href(p.url)?'<a href="'+href(p.url)+'" target="_blank" rel="noopener">Open resource ↗</a>':'')+'</div></article>').join('')||empty('No briefings posted yet.',leadership?'Publish the first set of priorities for a department.':'Briefings and approved resources will appear here.'));
 const f=box.querySelector('form');if(f)formBind(f,v=>read(sb.rpc('elan_ops_brief',{p_department:v.dept,p_title:v.title,p_body:v.body})));if(lead)composer(box.querySelector('[data-compose]'),{sb,dept:mine.department,after:()=>render('briefs')});return;}
 if(tab==='handoffs'){if(!leadership){await handoffDesk(box,sb,mine.department,lead);return;}box.innerHTML=s.handoffs.map(h=>'<article class="ops-row"><div><small>'+esc(h.department)+'</small><h3>'+esc(h.brief)+'</h3><p>'+esc(h.status)+'</p></div></article>').join('')||empty('No handoffs yet.','When a partnership commitment assigns work to another team, its owner and progress appear here.');return;}
 if(tab==='money'){const bal=k=>{const r=s.finance.find(x=>x.account===k);return r?Number(r.debit)-Number(r.credit):0;};box.innerHTML='<div class="ops-metrics">'+[['Available funds',bal('Funds')],['Income',-bal('Income')],['Expenses',bal('Expenses')],['Outstanding bills',-bal('Bills payable')]].map(([k,v])=>'<article><small>'+k+'</small><b>'+formatMoney(v)+'</b></article>').join('')+'</div><section class="ops-paper"><h2>Account balances</h2>'+ (s.finance.map(a=>'<p>'+esc(a.account)+' · Debit '+formatMoney(a.debit)+' · Credit '+formatMoney(a.credit)+'</p>').join('')||empty('No posted transactions yet.','Finance submits entries with evidence. The ledger updates after both leadership approvals.'))+btn('decisions','Review pending submissions')+'</section>';}
 }catch(err){if(g===generation){panel.innerHTML=empty('This section could not load.',err.message)+btn(active,'Try again');}}}
 await render('home');
}
